        },
        {
          "@type": "Question",
          "name": "¿Necesito licencia para alquilar una bicicleta?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No hace falta licencia de conducir. Las bicicletas no son motorizadas, así que cualquiera puede alquilar una con un documento de identidad válido."
