        {
          "@type": "Question",
          "name": "Vilka storlekar finns?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Vi har rullskridskor i EU-storlekar 35 till 42. Du kan prova olika storlekar i butiken för att hitta den bekvämaste."
