(function(){
  var form = document.getElementById('rsbContactForm');
  if (!form) return;

  form.addEventListener('submit', function(event){
    event.preventDefault();

    var name = (document.getElementById('contactName') || {}).value || '';
    var phone = (document.getElementById('contactPhone') || {}).value || '';
    var email = (document.getElementById('contactE-mail') || {}).value || '';
    var topic = (document.getElementById('contactTopic') || {}).value || '';
    var message = (document.getElementById('contactMessage') || {}).value || '';

    if (!name.trim() || !email.trim() || !message.trim()) {
      alert('Veuillez indiquer votre nom, votre email et votre message.');
      return;
    }

    var whatsappMessage = [
      'Bonjour RSB, je souhaite vous contacter depuis le site web.',
      '',
      'Nom: ' + name.trim(),
      'Téléphone / WhatsApp: ' + phone.trim(),
      'E-mail: ' + email.trim(),
      'Sujet: ' + topic.trim(),
      '',
      'Message:',
      message.trim()
    ].join('\n');

    var whatsappUrl = 'https://wa.me/34640559468?text=' + encodeURIComponent(whatsappMessage);
    window.location.href = whatsappUrl;
  });
})();

